import { createRequestHandler } from "react-router";
import type { ServerBuild } from "react-router";
import { deliverReminders, type ReminderEnv } from "../app/lib/email-reminders.server";
import { cleanupDocuments } from "../app/lib/student-documents.server";
import { deleteHandledReports } from "../app/lib/catalogue-report-retention.server";
// Generated by `npm run build`; Workers bundles this Web Streams-only server build.
// @ts-expect-error generated build has no source declaration
import * as generatedBuild from "../build/server/index.js";

type WorkerExecutionContext = { waitUntil(promise: Promise<unknown>): void };
type WorkerEnv = ReminderEnv & Record<string, unknown> & { ASSETS: { fetch(request: Request): Promise<Response> } };
const build = generatedBuild as ServerBuild;
// This entry is bundled by Wrangler, which does not inject Vite's import.meta.env.
const handleRequest = createRequestHandler(build, "production");

export default {
  fetch(request: Request, env: WorkerEnv, ctx: WorkerExecutionContext) {
    const pathname = new URL(request.url).pathname;
    if (pathname.startsWith("/assets/") || pathname.startsWith("/fonts/") || pathname === "/scholarable-mark.svg") return env.ASSETS.fetch(request);
    return handleRequest(request, { cloudflare: { env, ctx } });
  },
  async scheduled(_controller: unknown, env: WorkerEnv) {
    await Promise.all([deliverReminders(env), cleanupDocuments(env), deleteHandledReports(env)]);
  },
};
